 async http(path,payload){const {identity,token}=await this.credentials(),endpoint=await this.service();let response;try{response=await fetch(endpoint+path,{method:'POST',headers:{Authorization:'Bearer '+token,'Content-Type':'application/json'},body:JSON.stringify(payload),signal:AbortSignal.timeout(120000)});}catch{throw Error('No se pudo confirmar el envío. Pulsa Reintentar para comprobarlo sin duplicar el aviso.');}const result=await response.json();if(ClubAuth.user?.uid!==identity.uid)throw Error('La sesión ha cambiado.');if(!response.ok)throw Error(result.error||'No se pudo completar el envío.');return result;},
