  card.querySelector('h3').textContent='Editar aviso programado';form.dataset.notificationEdit=id;form.dataset.revision=v.revision;form.dataset.imageUrl=v.imageUrl;
  for(const key of ['title','body','teamKey'])form.elements[key].value=v[key];form.elements.mode.innerHTML='<option value="scheduled">Programar mensaje</option>';form.elements.scheduledAt.value=this.localDate(v.scheduledAt);
  const close=document.createElement('button');close.type='button';close.dataset.notificationEditClose='';close.className='text-action';close.textContent='Volver al historial';card.prepend(close);
