   this.historyRows.set(id,{id,status,title:f.title?.stringValue||'',body:f.body?.stringValue||'',teamKey:f.teamKey?.stringValue||'all',imageUrl:f.imageUrl?.stringValue||'',scheduledAt:Date.parse(date),revision:Number(f.revision?.integerValue||0)});
