   return `<article class="notification-history-item"><strong>${E(f.title?.stringValue||'Aviso')}</strong><p>${E(f.body?.stringValue||'')}</p><small>${E(states[status]||'Pendiente')} · ${date?E(new Date(date).toLocaleString('es-ES',{timeZone:'Europe/Madrid'})):''}${status==='sent'&&f.acceptedCount?` · ${Number(f.acceptedCount.integerValue||0)} dispositivos`:''}</small>${status==='scheduled'&&valid?`<div class="notification-actions"><button type="button" data-notification-edit="${id}">Editar</button><button type="button" data-notification-cancel="${id}" class="account-danger">Eliminar</button></div><div data-notification-cancel-prompt hidden><p>¿Eliminar este aviso programado? No se enviará.</p><button type="button" data-notification-cancel-confirm="${id}" class="account-danger">Eliminar aviso</button><button type="button" data-notification-cancel-close>Volver</button></div>`:''}${['pending','sending'].includes(status)&&valid?`<button type="button" data-notification-retry="${id}" class="text-action">Reintentar envío</button>`:''}</article>`;
