const adultRequest=ClubAuth.request.bind(ClubAuth);
ClubAuth.request=async function(action,...args){const result=await adultRequest(action==='state'&&ClubFamilies.adult&&this.firebase()?'resume':action,...args);if(action==='state'&&!ClubFamilies.adult&&result?.accountAccess){ClubFamilies.consent();return adultRequest('resume');}return result;};
const accountScreen=ClubAuth.screen.bind(ClubAuth),accountPerform=ClubAuth.perform.bind(ClubAuth);
ClubAuth.screen=function(...args){if(this.user&&!window.ClubDeletion?.pending&&!ClubFamilies.ready()){if(ClubFamilies.uid!==this.user.uid||!ClubFamilies.loading&&!ClubFamilies.checked&&!ClubFamilies.error)queueMicrotask(()=>ClubFamilies.load());return '<div class="auth-layout">'+ClubFamilies.birthdayScreen()+'</div>';}return accountScreen(...args);};
// Signing in is the consent step; the birth date screen right after it keeps accounts for people aged 14 or over.
// The native shell forgets consent on logout, so it is renewed before every sign-in.
ClubAuth.perform=async function(action,...args){if(['login','register','google'].includes(action)){ClubFamilies.consent();if(this.native())await adultRequest('resume');}await accountPerform(action,...args);if(this.user)await ClubFamilies.load();if(action==='logout'){ClubFamilies.clear();window.dispatchEvent(new CustomEvent('club-auth-view'));}};
