ClubAccess.sync=async function(...args){if(!ClubFamilies.adult)return;return clubSync(...args);};
ClubAccess.user=function(...args){return ClubFamilies.ready()?clubUser(...args):null;};
ClubAccess.administrator=function(...args){return ClubFamilies.ready()&&clubAdmin(...args);};
ClubFavorites.sync=async function(...args){if(!ClubFamilies.ready())return;return favoritesSync(...args);};
