document.addEventListener('submit',async event=>{const form=event.target.closest('[data-adult-access],[data-account-birthday]');if(!form)return;event.preventDefault();const feedback=form.querySelector('[data-adult-feedback],[data-birthday-feedback]');if(form.dataset.saving)return;try{if(!form.elements.privacy.checked)throw Error('Lee la política de privacidad antes de continuar.');if(form.matches('[data-adult-access]')){if(!form.elements.adult.checked)throw Error('Confirma que la cuenta es de una persona adulta.');ClubFamilies.consent();await ClubAuth.request('resume');await ClubAccess.sync();window.dispatchEvent(new CustomEvent('club-auth-view'));return;}const birthDate=form.elements.adultBirthDate.value;if(!ClubFamilies.check(birthDate)){ClubFamilies.minor=true;throw Error('Las cuentas son para mayores de 14 años. Puedes consultar la app sin cuenta o pedir a tu padre, madre o tutor que use la suya.');}const uid=ClubAuth.user?.uid,revision=ClubFamilies.revision;form.dataset.saving='true';form.querySelector('button[type="submit"]').disabled=true;await ClubFamilies.http('POST',{birthDate,privacyAccepted:true});if(uid!==ClubAuth.user?.uid||revision!==ClubFamilies.revision)return;ClubFamilies.birthDate=birthDate;ClubFamilies.checked=true;ClubFamilies.minor=false;ClubFamilies.remember(uid);await ClubAccess.sync();window.dispatchEvent(new CustomEvent('club-auth-view'));}catch(error){feedback.textContent=error.message;}finally{delete form.dataset.saving;const button=form.querySelector('button[type="submit"]');if(button)button.disabled=false;}});
