 async http(method,payload){const identity=ClubAuth.user;if(!identity)throw Error('Inicia sesión para cambiar tu foto.');const credentials=await ClubAuth.request('token');if(!credentials.token||credentials.user?.uid!==identity.uid||ClubAuth.user?.uid!==identity.uid)throw Error('La sesión ha cambiado.');const endpoint=await ClubNotifications.service();const response=await fetch(endpoint+'/profile/photo',{method,headers:{Authorization:'Bearer '+credentials.token,'Content-Type':'application/json'},...(payload?{body:JSON.stringify(payload)}:{}),signal:AbortSignal.timeout(60000)});const data=await response.json();if(ClubAuth.user?.uid!==identity.uid)throw Error('La sesión ha cambiado.');if(!response.ok)throw Error(data.error||'No se pudo guardar la foto.');return data;},
 async load(){const identity=ClubAuth.user;if(!identity){this.uid='';this.photoURL='';this.blob='';this.clear();this.revision++;return;}if(!ClubAccess.user()?.active||this.uid===identity.uid)return;this.uid=identity.uid;this.photoURL='';const revision=++this.revision;try{const data=await this.http('GET');if(revision!==this.revision||ClubAuth.user?.uid!==identity.uid)return;this.photoURL=this.safe(data.photoURL);this.blob=this.photoURL?await ClubMedia.load(this.photoURL):'';if(revision!==this.revision||ClubAuth.user?.uid!==identity.uid)return;window.dispatchEvent(new CustomEvent('club-auth-view'));}catch{if(revision===this.revision)this.uid='';}},
