 // Socios page: markup is static; mounted() fills it so timers can update the QR in place.
 // The card's season comes from the date the fee is paid until (30 June), or from today's date.
 seasonShort(card=this.card){if(card?.season?.short)return card.season.short;const end=/^\d{4}-\d{2}-\d{2}$/.test(card?.paidUntil||'')?new Date(card.paidUntil+'T12:00:00Z'):null,d=end||new Date(),y=d.getUTCMonth()>=6?d.getUTCFullYear():d.getUTCFullYear()-1;return String(y).slice(2)+'/'+String(y+1).slice(2);},
 screen(){return `<div class="section-heading"><h2>Zona de socios</h2><span>TEMPORADA ${this.seasonShort()}</span></div><div data-member-root>${this.cardMarkup()}</div>`;},
 // The season's card design uploaded by the club (front and back), or the default design.
 design:null,designKey:'cdm-card-design-v1',
