 async loadDesign(){
  const want=this.card?.season?.design;if(!want||this.design?.updatedAt===want)return;
  try{const saved=JSON.parse(localStorage.getItem(this.designKey)||'null');if(saved?.updatedAt===want){this.design=saved;return;}}catch{}
  try{const d=await this.http('/member/card-design');if(d.front&&d.updatedAt===want){this.design=d;try{localStorage.setItem(this.designKey,JSON.stringify(d));}catch{}}}catch{}
 },
 cardMarkup(){
  const E=this.E.bind(this),c=this.card;
  if(this.error&&!c)return `<section class="card member-message"><p role="alert">${E(this.error)}</p><button type="button" class="auth-secondary" data-member-retry>Reintentar</button></section>`;
  if(!c)return `<section class="card member-message"><p role="status">Cargando tu carnet…</p></section>`;
  const [tone,label]=this.status(c),f=this.faces(),expires=c.season?.expires;
  return `<div class="member-card${this.flipped?' is-flipped':''}${f.custom?' custom':''}"${f.custom?` style="--card-ratio:${Number(f.ratio)||0.642}"`:''}><button type="button" class="member-card-inner" data-member-flip aria-pressed="${this.flipped}" aria-label="${this.flipped?'Mostrar la parte delantera del carnet':'Mostrar el código QR del carnet'}"><span class="member-face member-front"><img src="${E(f.front)}" alt="Carnet de socio del CD Menciana, temporada ${E(this.seasonShort(c))}"></span><span class="member-face member-back">${f.back?`<img src="${E(f.back)}" alt="">`:''}<span class="member-qr${f.custom?' custom':''}" data-member-qr>${c.memberNumber?'':'<small>Sin número de socio</small>'}</span></span></button></div>
  <p class="member-hint">${this.flipped?'Enséñalo en la puerta. Es tu código personal para toda la temporada.':'Pulsa el carnet para mostrar tu código QR.'}</p>
  <section class="card member-details"><div><small>SOCIO</small><strong>${E(c.name)}</strong></div><div><small>Nº DE SOCIO</small><strong>${c.memberNumber?E(c.memberNumber):'Pendiente'}</strong></div><p class="member-status ${tone}">${E(label)}</p>${expires?`<p class="member-expiry">Carnet válido hasta el <b>${E(this.date(expires))}</b></p>`:''}${c.memberNumber?'':'<p class="member-note">El club te asignará tu número de socio. Después aparecerá tu código QR.</p>'}${this.error?`<p role="alert">${E(this.error)}</p>`:''}</section>${c.memberNumber&&c.token?'<button type="button" class="auth-secondary member-pdf" data-member-pdf>Descargar carnet en PDF</button><p class="member-pdf-status" data-member-pdf-status role="status"></p>':''}`;
 },
 image(src){return new Promise((resolve,reject)=>{const img=new Image();img.onload=()=>resolve(img);img.onerror=()=>reject(Error('No se pudo cargar el diseño del carnet.'));img.src=src;});},
