  const drawQr=(doc,x,y,size)=>{const m=size/n;doc.setFillColor(255,255,255);doc.rect(x,y,size,size,'F');doc.setFillColor(16,28,48);for(let r=0;r<n;r++)for(let k=0;k<n;k++)if(qr.isDark(r,k))doc.rect(x+k*m,y+r*m,m+0.02,m+0.02,'F');};
