  doc.setFont('helvetica','bold');doc.setFontSize(18);doc.setTextColor(24,44,70);doc.text('CD Menciana · Carnet de socio',M,22);
  doc.setFont('helvetica','normal');doc.setFontSize(10);doc.setTextColor(90);doc.text('Temporada '+c.short,M,28);
