  const ratio=f.ratio||720/1122,cw=ratio>1?84:62,ch=cw/ratio,top=36,gap=ratio>1?8:14,x1=(W-2*cw-gap)/2,x2=x1+cw+gap;
  doc.addImage(front,'JPEG',x1,top,cw,ch);if(back)doc.addImage(back,'JPEG',x2,top,cw,ch);else{doc.setFillColor(24,35,53);doc.roundedRect(x2,top,cw,ch,3,3,'F');}
  const qs=f.custom?Math.min(cw,ch)*0.62:cw*0.35,qx=f.custom?x2+(cw-qs)/2:x2+cw*0.236,qy=f.custom?top+(ch-qs)/2:top+ch*0.594,pad=qs*0.086;doc.setFillColor(255,255,255);doc.roundedRect(qx,qy,qs,qs,2,2,'F');drawQr(doc,qx+pad,qy+pad,qs-2*pad);
  doc.setDrawColor(200);doc.setLineDashPattern([1.5,1.5],0);doc.rect(x1-2,top-2,cw*2+gap+4,ch+4);doc.setLineDashPattern([],0);
  doc.setFontSize(8);doc.setTextColor(130);doc.text('Si lo imprimes, recorta por la línea de puntos.',W/2,top+ch+7,{align:'center'});
  // A large code on its own, easy to scan from the phone screen or to add to a wallet app.
  let y=top+ch+18;const big=64,bx=(W-big)/2;drawQr(doc,bx,y,big);doc.setDrawColor(220);doc.roundedRect(bx-4,y-4,big+8,big+8,3,3);y+=big+13;
  doc.setFont('helvetica','bold');doc.setFontSize(15);doc.setTextColor(24,44,70);doc.text(c.name||'Socio',W/2,y,{align:'center'});y+=7;
  doc.setFont('helvetica','normal');doc.setFontSize(11);doc.text('Nº de socio '+c.memberNumber+' · Código válido hasta el '+season,W/2,y,{align:'center'});y+=9;
  doc.setFontSize(8.5);doc.setTextColor(110);
  doc.text(doc.splitTextToSize('Documento personal e intransferible. Enséñalo en la puerta desde el móvil o impreso. En cada escaneo se comprueba que la cuota está al día, y en cada partido solo se puede entrar una vez con el mismo carnet. Para guardarlo en una app de cartera, añade una tarjeta escaneando el código QR grande.',W-2*M-20),W/2,y,{align:'center'});
