 memberForm(m){const E=this.E.bind(this);return `<form class="sm-form" data-sm-form data-previous="${m?E(m.memberNumber):''}"><div class="sm-grid"><label class="auth-field"><span>Nº de socio</span><input name="memberNumber" inputmode="numeric" pattern="[0-9]{1,12}" maxlength="12" required value="${m?E(m.memberNumber):''}"></label><label class="auth-field sm-wide"><span>Nombre</span><input name="name" maxlength="120" required value="${m?E(m.name):''}"></label><label class="auth-field"><span>DNI</span><input name="dni" maxlength="12" autocomplete="off" value="${m?E(m.dni):''}"></label><label class="auth-field"><span>Teléfono</span><input name="phone" inputmode="tel" maxlength="20" autocomplete="off" value="${m?E(m.phone):''}"></label></div><label class="privacy-check"><input type="checkbox" name="paid"${m?.paid?' checked':''}>Cuota de la temporada pagada</label><div class="season-actions"><button type="submit" class="auth-primary">${m?'Guardar cambios':'Añadir socio'}</button><button type="button" class="auth-secondary" data-sm-cancel>Cancelar</button></div></form>`;},
 smRows(){
  const E=this.E.bind(this),d=this.seasonList;if(!d)return '<p role="status">Cargando socios…</p>';if(d.error)return `<p role="alert">${E(d.error)}</p>`;
  const q=this.smFilter.trim().toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,''),rows=d.members.filter(m=>!q||m.memberNumber.startsWith(q)||m.name.toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'').includes(q));
  if(!rows.length)return `<p>${d.members.length?'Ningún socio coincide con la búsqueda.':'Todavía no hay socios en esta temporada.'}</p>`;
  return `<ul class="sm-list">${rows.slice(0,400).map(m=>this.smEdit===m.memberNumber?`<li class="is-editing">${this.memberForm(m)}</li>`:`<li><div><b>Nº ${E(m.memberNumber)}</b> <span>${E(m.name||'Sin nombre')}</span><small>${[m.dni&&'DNI '+m.dni,m.phone].filter(Boolean).map(E).join(' · ')||'Sin DNI ni teléfono'}</small><em class="member-status ${m.paid?'active':'pending'}">${m.paid?'Pagada':'Pendiente'}</em></div><div class="sm-actions"><button type="button" class="auth-secondary" data-sm-qr="${E(m.memberNumber)}">Carnet</button><button type="button" class="auth-secondary" data-sm-edit="${E(m.memberNumber)}">Editar</button><button type="button" class="text-action event-delete" data-sm-del="${E(m.memberNumber)}">Quitar</button></div></li>`).join('')}</ul>${rows.length>400?'<p>Mostrando los 400 primeros: busca para encontrar al resto.</p>':''}`;
 },
 editorMarkup(){
  const E=this.E.bind(this),x=this.seasons.seasons.find(s=>s.id===this.editSeason);if(!x){this.editSeason='';return this.seasonsMarkup();}
  return `<div class="season-editor"><button type="button" class="event-back" data-season-back>← Temporadas</button>
  <h4>${E(x.label)}${x.current?' <span class="event-live">Activa</span>':''}</h4><p>${E(this.rosterText(x.roster))}</p>
  <form class="season-new" data-card-expiry="${E(x.id)}"><label class="auth-field"><span>Caducidad del carnet</span><input type="date" name="expires" value="${E(x.expires||x.end)}" required></label><button type="submit" class="auth-secondary">Guardar fecha</button></form>
  <div class="season-actions"><button type="button" class="auth-primary" data-sm-new>Añadir socio</button><button type="button" class="auth-secondary" data-season-passes="${E(x.id)}"${x.roster?.count?'':' disabled'}>QR de todos (PDF)</button><label class="auth-secondary member-roster-file">Sustituir listado (PDF o CSV)<input type="file" accept="application/pdf,.pdf,.csv,text/csv" data-roster-file data-season="${E(x.id)}" data-season-short="${E(x.short)}" hidden></label></div>
  ${this.smEdit==='new'?this.memberForm(null):''}
  <label class="auth-field sm-search"><span>Buscar socio</span><input type="search" data-sm-search placeholder="Número o nombre" value="${E(this.smFilter)}" autocomplete="off"></label>
  <div data-sm-list>${this.smRows()}</div></div>`;
 },
 async openSeason(id){this.editSeason=id;this.seasonList=null;this.smFilter='';this.smEdit='';this.seasonStatus='';this.paintSeasons();document.querySelector('[data-seasons-root]')?.scrollIntoView({block:'start'});
  try{this.seasonList=await this.http('/admin/seasons/'+id+'/members');}catch(e){this.seasonList={error:e.message,members:[]};}if(this.editSeason===id)this.paintSeasons();},
